const payload = $('Execute Workflow Trigger').item.json || {};
const chatId = String(payload.chatId || payload.message?.chat?.id || '').trim();
const limit = Math.max(1, Math.min(10, Number(payload.limit || 5) || 5));
if (!chatId) {
  throw new Error('Missing chatId for memory_recent');
}
return [{ json: { chatId, limit } }];

const source = $('Prepare Memory Recent').item.json || {};
const rows = $input.all().map((item) => item.json || {}).filter((row) => row.id);
if (rows.length === 0) {
  return [{
    json: {
      chatId: source.chatId || '',
      text: 'Memory gần đây:\n(chưa có mục nào)',
      result: { items: [] }
    }
  }];
}
const lines = ['Memory gần đây:'];
const items = rows.map((row) => {
  const title = String(row.title || '').trim();
  const content = String(row.content || '').trim();
  const snippet = content.length > 220 ? `${content.slice(0, 220).trim()}...` : content;
  const tags = Array.isArray(row.tags) ? row.tags : [];
  const updatedAt = row.updated_at ? new Date(row.updated_at).toLocaleString('vi-VN', { timeZone: 'Asia/Ho_Chi_Minh', hour12: false }) : '';
  return {
    id: row.id,
    memory_type: row.memory_type || 'general',
    title,
    content,
    snippet,
    tags,
    importance: row.importance || 3,
    updated_at: row.updated_at || null,
    updated_at_display: updatedAt
  };
});
items.forEach((item, index) => {
  const title = item.title ? ` ${item.title}:` : '';
  const tags = item.tags.length ? ` | tags=${item.tags.join(', ')}` : '';
  const updated = item.updated_at_display ? ` | cập nhật ${item.updated_at_display}` : '';
  lines.push(`${index + 1}. [${item.memory_type}]${title} ${item.snippet}${tags}${updated}`.trim());
});
return [{
  json: {
    chatId: source.chatId || '',
    text: lines.join('\n'),
    result: { items }
  }
}];
